import sys
sys.setrecursionlimit(10**6 + 5)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    if N == 1:
        print(1)
        return

    adj = [[] for _ in range(N + 1)]

    for _ in range(N - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (N + 1)
    depth = [0] * (N + 1)
    children_count = [0] * (N + 1)

    stack = [1]
    visited = [False] * (N + 1)
    visited[1] = True
    order = []

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)

    for i in range(len(order) - 1, -1, -1):
        u = order[i]
        count = 0
        for v in adj[u]:
            if v != parent[u]:
                count += 1
        children_count[u] = count

    leaves = []
    for i in range(1, N + 1):
        if children_count[i] == 0:
            leaves.append(i)

    if not leaves:
        print(1)
        return

    max_depth_leaf = 0
    for l in leaves:
        if depth[l] > max_depth_leaf:
            max_depth_leaf = depth[l]

    min_depth_leaf = float('inf')
    for l in leaves:
        if depth[l] < min_depth_leaf:
            min_depth_leaf = depth[l]

    if max_depth_leaf == min_depth_leaf:
        print(len(leaves))
        return

    ans = 0
    for d in range(min_depth_leaf, max_depth_leaf + 1):
        count = 0
        for l in leaves:
            if depth[l] >= d:
                count += 1
        if count > 0:
            ans = max(ans, count)

    print(ans)

if __name__ == "__main__":
    main()
